});

export function settingsRoutes(deps: RouteDeps): Hono<AppEnv> {
  const app = new Hono<AppEnv>();

  // --- Model keys (BYOK, ADR-0005) ---
  app.get("/model-keys", async (c) => {
    const keys = await listModelKeys(deps.prisma, c.get("workspaceId"));
